package com.example.water;
import java.net.URI;import java.net.http.*;import java.time.Duration;
public final class LeakClient{private final String base;private final HttpClient h=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).build();public LeakClient(String b){base=b.replaceAll("/$","");}public String score()throws Exception{var q=HttpRequest.newBuilder(URI.create(base+"/v1/risk")).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{\"segment_id\":\"SEG-DEMO\",\"pressure_drop_bar\":0.3,\"flow_cv\":0.2,\"pipe_age_years\":22,\"repairs_5y\":1,\"soil_risk\":0.4}")).build();var r=h.send(q,HttpResponse.BodyHandlers.ofString());if(r.statusCode()/100!=2)throw new IllegalStateException(r.body());return r.body();}public static void main(String[]a)throws Exception{System.out.println(new LeakClient(a.length>0?a[0]:"http://127.0.0.1:8000").score());}}
